begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('96000000-0000-0000-0000-000000000009','measurements@example.test');
update public.profiles set active=true,role='DISPATCHER' where id='96000000-0000-0000-0000-000000000009';
select set_config('test.request',(select id::text from public.moving_requests where request_number='LM-001005'),true);
update public.moves set status='IN_PROGRESS',version=1,finished_at=null,actual_miles=null,final_total_cents=null where request_id=current_setting('test.request')::uuid;
update public.moving_requests set status='IN_PROGRESS' where id=current_setting('test.request')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','96000000-0000-0000-0000-000000000009',true);
select lives_ok($$select public.record_move(current_setting('test.request')::uuid,1,'save',now()-interval '4 hours',null,null)$$,'local: partial save');
select throws_ok($$select public.record_move(current_setting('test.request')::uuid,2,'complete',now()-interval '4 hours',null,null)$$,'P0001','INVALID_INPUT','local: missing finish cannot close');
select lives_ok($$select public.record_move(current_setting('test.request')::uuid,2,'save',now()-interval '4 hours',now()-interval '1 hour',null)$$,'local: full save');
select ok((select finished_at=now()-interval '1 hour' and started_at=now()-interval '4 hours' and version=3 and status='IN_PROGRESS' and final_total_cents is null from public.moves where request_id=current_setting('test.request')::uuid),'local: times and version persist without closing');
select ok(exists(select 1 from public.pricing_change_history where request_id=current_setting('test.request')::uuid and field='finished_at' and new_value=to_jsonb(now()-interval '1 hour')),'local: finish audited');
select throws_ok($$select public.record_move(current_setting('test.request')::uuid,2,'save',now()-interval '4 hours',null,null)$$,'P0001','CONFLICT','local: stale save cannot erase finish');
select lives_ok($$select public.record_move(m.request_id,m.version,'complete',m.started_at,m.finished_at,m.actual_miles) from public.moves m where request_id=current_setting('test.request')::uuid$$,'local: complete using reloaded values');
select is((select final_total_cents from public.moves where request_id=current_setting('test.request')::uuid),35700::bigint,'local: expected total');
select is((select status from public.moving_requests where id=current_setting('test.request')::uuid),'COMPLETED','local: request synchronized');
select throws_ok($$select public.record_move(m.request_id,m.version,'correct',m.started_at,m.finished_at,m.actual_miles) from public.moves m where request_id=current_setting('test.request')::uuid$$,'42501',null,'local: dispatcher cannot correct after closing');
reset role;
select set_config('test.request',(select id::text from public.moving_requests where request_number='LM-001004'),true);
update public.moves set status='IN_PROGRESS',version=1,finished_at=null,actual_miles=null,final_total_cents=null where request_id=current_setting('test.request')::uuid;
update public.moving_requests set status='IN_PROGRESS' where id=current_setting('test.request')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','96000000-0000-0000-0000-000000000009',true);
select lives_ok($$select public.record_move(current_setting('test.request')::uuid,1,'save',now()-interval '4 hours',null,205)$$,'mile: partial save');
select throws_ok($$select public.record_move(current_setting('test.request')::uuid,2,'complete',now()-interval '4 hours',null,205)$$,'P0001','INVALID_INPUT','mile: missing finish cannot close');
select lives_ok($$select public.record_move(current_setting('test.request')::uuid,2,'save',now()-interval '4 hours',now()-interval '1 hour',205)$$,'mile: full save');
select ok((select finished_at=now()-interval '1 hour' and started_at=now()-interval '4 hours' and version=3 and status='IN_PROGRESS' and final_total_cents is null from public.moves where request_id=current_setting('test.request')::uuid),'mile: times and version persist without closing');
select ok(exists(select 1 from public.pricing_change_history where request_id=current_setting('test.request')::uuid and field='finished_at' and new_value=to_jsonb(now()-interval '1 hour')),'mile: finish audited');
select throws_ok($$select public.record_move(current_setting('test.request')::uuid,2,'save',now()-interval '4 hours',null,205)$$,'P0001','CONFLICT','mile: stale save cannot erase finish');
select lives_ok($$select public.record_move(m.request_id,m.version,'complete',m.started_at,m.finished_at,m.actual_miles) from public.moves m where request_id=current_setting('test.request')::uuid$$,'mile: complete using reloaded values');
select is((select final_total_cents from public.moves where request_id=current_setting('test.request')::uuid),82000::bigint,'mile: expected total');
select is((select status from public.moving_requests where id=current_setting('test.request')::uuid),'COMPLETED','mile: request synchronized');
select throws_ok($$select public.record_move(m.request_id,m.version,'correct',m.started_at,m.finished_at,m.actual_miles) from public.moves m where request_id=current_setting('test.request')::uuid$$,'42501',null,'mile: dispatcher cannot correct after closing');
reset role;
select * from finish();
rollback;
